#!/usr/bin/env node
// meshcheck.mjs — PLAN F8's acceptance test. The one Dan asked for by name:
//
//   "mchtml is having issues with block rotation and states and looks and i dont even want
//    to have to think about that."
//
//   node tools/meshcheck.mjs
//
// ⚠ WHERE THE REFERENCE COMES FROM, because it is the only thing that makes this test worth
// running. A reference generated by the same pipeline proves self-consistency and nothing
// else — the exact failure `modelcheck.mjs`'s anti-vacuity section exists to prevent. So
// every expectation below was derived by hand from the model JSON in the jar and from
// Mojang's own conventions, and each one names the file it came from. Anyone can re-read
// those files and check this test rather than trusting it.
//
// Two defects were caught here or by its siblings before it passed, both now fixed:
//   1. placement rotation used the standard right-handed convention; Mojang's is the
//      opposite. Every stair, trapdoor, torch, log, chest, furnace and door was rotated
//      the wrong way — 96% of the roster — and stone looked fine throughout.
//   2. the occlusion plane for max-side faces was 15 instead of 16, so nothing in the game
//      ever occluded upward.

import { readFileSync } from 'node:fs';
import { CASES as REFERENCE } from './mesh-reference.mjs';
import { join } from 'node:path';

// The project root, derived from THIS FILE's location rather than hard-coded. Every tool
// here used to hard-code an absolute path, which meant the whole suite ran
// on exactly one machine — the checks synced to Dan's copy could not be run there at all.
import { fileURLToPath } from 'node:url';
const MCLITE_ROOT = fileURLToPath(new URL('..', import.meta.url));   // ends with a separator


const OUT = process.argv.includes('--out') ? process.argv[process.argv.indexOf('--out') + 1]
  : MCLITE_ROOT + 'assets';
const rd = (f) => JSON.parse(readFileSync(join(OUT, f), 'utf8'));

const G = rd('block-geometry.json');
const registry = rd('block-registry.json');
const atlas = rd('atlas-index.json');
const byName = new Map(registry.map((e) => [e.name, e]));
const tileOf = new Map(Object.entries(atlas.index).map(([k, v]) => [v, k]));
const DIRS = ['down', 'up', 'north', 'south', 'west', 'east'];

let pass = 0; const fails = [];
const ok = (cond, msg) => { if (cond) pass++; else fails.push(msg); };
const eq = (a, b, msg) => ok(JSON.stringify(a) === JSON.stringify(b), `${msg}\n        expected ${JSON.stringify(b)}\n        actual   ${JSON.stringify(a)}`);

/** Every quad of a block in a given state, flattened. */
function quads(name, want, alt = 0) {
  const e = byName.get(name);
  if (!e) throw new Error('no such block ' + name);
  const i = e.states.findIndex((s) => Object.entries(want).every(([k, v]) => s.state[k] === v));
  if (i < 0) throw new Error(`${name} has no state matching ${JSON.stringify(want)}`);
  return G.states[name][i].flatMap((g) => G.parts[typeof g === 'number' ? g : g.a[alt % g.a.length]]);
}
/** Every ALTERNATIVE of the one-of group at index gi — used to test random variation. */
function alternatives(name, want, gi = 0) {
  const e = byName.get(name);
  const i = e.states.findIndex((s) => Object.entries(want).every(([k, v]) => s.state[k] === v));
  const g = G.states[name][i][gi];
  return typeof g === 'number' ? [G.parts[g]] : g.a.map((p) => G.parts[p]);
}
const face = (qs, d) => qs.filter((q) => q.d === DIRS.indexOf(d));
const bbox = (qs) => {
  const lo = [Infinity, Infinity, Infinity], hi = [-Infinity, -Infinity, -Infinity];
  for (const q of qs) for (let c = 0; c < 4; c++) for (let a = 0; a < 3; a++) {
    lo[a] = Math.min(lo[a], q.p[c * 3 + a]); hi[a] = Math.max(hi[a], q.p[c * 3 + a]);
  }
  return [lo, hi];
};
const tex = (q) => tileOf.get(q.t);

// ══════════════════════════════════════════════════ 1. the full cube
// Reference: block/cube_all -> block/cube, element from [0,0,0] to [16,16,16], six faces,
// each with cullface equal to its own direction. Read from the jar by hand.
console.log('1. full cube (stone)');
{
  const q = quads('stone', {});
  ok(q.length === 6, `stone should be 6 quads, is ${q.length}`);
  // ⚠ stone.json lists FOUR alternatives (stone, stone_mirrored, and each at y:180) that
  // vanilla picks between at random per position. They are one-of, not four-at-once —
  // drawing all four would quadruple every stone block in the world and z-fight. This
  // assertion is the reason `groupsFor()` exists; meshcheck caught it as "stone has 4
  // south faces" on its first run.
  const alts = alternatives('stone', {});
  ok(alts.length === 4, `stone should offer 4 random alternatives, offers ${alts.length}`);
  ok(alts.every((a) => a.length === 6), 'every stone alternative must itself be 6 quads');
  ok(new Set(alts.map((a) => JSON.stringify(a))).size > 1, 'the stone alternatives must differ from each other');
  eq(bbox(q), [[0, 0, 0], [16, 16, 16]], 'stone bbox');
  for (const d of DIRS) {
    const f = face(q, d);
    ok(f.length === 1, `stone has ${f.length} ${d} faces, expected 1`);
    if (!f[0]) continue;
    eq(f[0].cull, DIRS.indexOf(d), `stone ${d} face must cull against ${d}`);
    eq(tex(f[0]), 'block/stone', `stone ${d} texture`);
    eq(f[0].uv, [0, 0, 16, 0, 16, 16, 0, 16], `stone ${d} uv must be the whole tile`);
    eq(f[0].tint, -1, `stone ${d} must not be tinted`);
  }
}
console.log(`   ${pass} ok`);

// ══════════════════════════════════════════════════ 2. slabs — the implicit-UV case
// Reference: block/slab, element [0,0,0]-[16,8,16]. Only `down` carries cullface "down";
// the side faces carry none, because a half-height side never fills a neighbour's face.
// The side UVs are IMPLICIT and must come out as [0,8,16,16] — v starts at 8, not 0.
console.log('2. slab (implicit UVs, the half-height case)');
{
  const q = quads('oak_slab', { type: 'bottom' });
  eq(bbox(q), [[0, 0, 0], [16, 8, 16]], 'bottom slab bbox is the lower half');
  ok(q.length === 6, `bottom slab should be 6 quads, is ${q.length}`);
  eq(face(q, 'down')[0].cull, DIRS.indexOf('down'), 'bottom slab down face culls down');
  eq(face(q, 'up')[0].cull, -1, 'bottom slab up face must NOT cull — nothing is above it');
  // ⚠ vanilla's block/slab.json DOES carry `cullface` on all four sides — a full block to
  // the north covers the slab's north face entirely, so it is correct to cull it. The first
  // draft of this test asserted the opposite and was wrong; the model file settles it.
  for (const d of ['north', 'south', 'east', 'west']) {
    eq(face(q, d)[0].cull, DIRS.indexOf(d), `bottom slab ${d} face culls against ${d}`);
    eq(face(q, d)[0].uv, [0, 8, 16, 8, 16, 16, 0, 16],
      `bottom slab ${d} uv must be the LOWER half of the tile (v 8..16), derived from the element extent`);
  }

  const top = quads('oak_slab', { type: 'top' });
  eq(bbox(top), [[0, 8, 0], [16, 16, 16]], 'top slab bbox is the upper half');
  eq(face(top, 'up')[0].cull, DIRS.indexOf('up'), 'top slab up face culls up');
  eq(face(top, 'down')[0].cull, -1, 'top slab down face must not cull');

  const dbl = quads('oak_slab', { type: 'double' });
  eq(bbox(dbl), [[0, 0, 0], [16, 16, 16]], 'double slab is a full cube');
  ok(dbl.length === 6, `double slab should be 6 quads, is ${dbl.length}`);
}
console.log(`   ${pass} ok`);

// ══════════════════════════════════════════════════ 3. stairs — the rotation case
// Reference: block/stairs has two elements — [0,0,0]-[16,8,16] and [8,8,0]-[16,16,16].
// The tall step is on the EAST, and oak_stairs.json gives facing=east NO rotation, so the
// base model IS facing=east. facing=south is y:90, facing=west y:180, facing=north y:270.
// Mojang's y90 turns east into south (four independent confirmations in models.mjs).
console.log('3. stairs (placement rotation — the bug that started this)');
{
  const base = quads('oak_stairs', { facing: 'east', half: 'bottom', shape: 'straight' });
  eq(bbox(base), [[0, 0, 0], [16, 16, 16]], 'a straight stair fills its cell corner to corner');

  // the tall step: for facing=east it must live in x 8..16, and its top face at y=16.
  const upFaces = face(base, 'up');
  const high = upFaces.filter((q) => q.p[1] === 16);
  ok(high.length === 1, `east stair should have exactly one up-face at y=16, has ${high.length}`);
  const hx = high[0] ? [high[0].p[0], high[0].p[3], high[0].p[6], high[0].p[9]] : [];
  eq([Math.min(...hx), Math.max(...hx)], [8, 16], 'east stair tall step sits in x 8..16');

  // rotate it and the tall step must follow. The mapping is the assertion.
  const WHERE = {
    east:  { axis: 0, lo: 8,  hi: 16 },   // +x
    south: { axis: 2, lo: 8,  hi: 16 },   // +z
    west:  { axis: 0, lo: 0,  hi: 8  },   // -x
    north: { axis: 2, lo: 0,  hi: 8  },   // -z
  };
  for (const [facing, w] of Object.entries(WHERE)) {
    const q = quads('oak_stairs', { facing, half: 'bottom', shape: 'straight' });
    const hi16 = face(q, 'up').filter((f) => f.p[1] === 16);
    ok(hi16.length === 1, `${facing} stair: ${hi16.length} up-faces at y=16, expected 1`);
    if (!hi16[0]) continue;
    const vs = [0, 1, 2, 3].map((c) => hi16[0].p[c * 3 + w.axis]);
    eq([Math.min(...vs), Math.max(...vs)], [w.lo, w.hi],
      `${facing} stair tall step must sit at ${'xyz'[w.axis]} ${w.lo}..${w.hi} — if this fails the placement rotation is backwards`);
    eq(bbox(q), [[0, 0, 0], [16, 16, 16]], `${facing} stair bbox`);
  }

  // top-half stairs mirror in Y: the step hangs from the ceiling.
  const top = quads('oak_stairs', { facing: 'east', half: 'top', shape: 'straight' });
  const down0 = face(top, 'down').filter((f) => f.p[1] === 0);
  ok(down0.length === 1, `top stair should have one down-face at y=0, has ${down0.length}`);
}
console.log(`   ${pass} ok`);

// ══════════════════════════════════════════════════ 4. uvlock
// Reference: oak_stairs.json marks every rotated variant `uvlock: true`. uvlock means the
// TEXTURE stays put while the geometry turns — so the up and down faces of a y-rotated
// stair must NOT have their UVs rotated with the model. The test: the set of UV corner
// pairs on the up face must be identical across all four facings, even though the geometry
// moved. Without uvlock the wood grain visibly spins as you place stairs around a pillar.
console.log('4. uvlock (the wood grain must not spin)');
{
  const sig = (facing) => {
    const q = quads('oak_stairs', { facing, half: 'bottom', shape: 'straight' });
    // the big low up-face at y=8 is present in every facing
    const f = face(q, 'up').find((x) => x.p[1] === 8);
    if (!f) return null;
    // compare the AXIS-ALIGNED uv extent, which uvlock preserves
    const us = [0, 2, 4, 6].map((i) => f.uv[i]), vs = [1, 3, 5, 7].map((i) => f.uv[i]);
    return [Math.min(...us), Math.min(...vs), Math.max(...us), Math.max(...vs)];
  };
  const ref = sig('east');
  ok(ref !== null, 'east stair has a low up-face at y=8');
  for (const facing of ['south', 'west', 'north']) {
    eq(sig(facing), ref, `${facing} stair's up-face uv extent must match east's — uvlock`);
  }
  // and the geometry really did move, or the test above would be vacuous
  const eastLow = face(quads('oak_stairs', { facing: 'east', half: 'bottom', shape: 'straight' }), 'up').find((x) => x.p[1] === 8);
  const westLow = face(quads('oak_stairs', { facing: 'west', half: 'bottom', shape: 'straight' }), 'up').find((x) => x.p[1] === 8);
  ok(JSON.stringify(eastLow.p) !== JSON.stringify(westLow.p),
    'ANTI-VACUITY: east and west stairs must have DIFFERENT geometry, or the uvlock test proves nothing');
}
console.log(`   ${pass} ok`);

// ══════════════════════════════════════════════════ 5. fences — multipart assembly
// Reference: oak_fence.json is multipart. The post (oak_fence_post) is unconditional; each
// side adds oak_fence_side with y rotations 0/90/180/270 for north/east/south/west.
// A fence with nothing connected is the post alone; with all four, post + four arms.
console.log('5. fence (multipart assembly and per-side rotation)');
{
  const none = quads('oak_fence', { north: 'false', south: 'false', east: 'false', west: 'false' });
  eq(bbox(none), [[6, 0, 6], [10, 16, 10]], 'a disconnected fence is just the 4x16x4 post');

  const all = quads('oak_fence', { north: 'true', south: 'true', east: 'true', west: 'true' });
  eq(bbox(all), [[0, 0, 0], [16, 16, 16]], 'a fully connected fence spans the whole cell');
  ok(all.length > none.length * 4, `fully connected fence has ${all.length} quads vs ${none.length} for the post alone`);

  // one arm at a time, and the arm must be on the named side. This is the assertion that
  // catches a multipart `when` clause being matched against the wrong property value.
  const REACH = { north: [2, 0], south: [2, 16], west: [0, 0], east: [0, 16] };
  for (const [side, [axis, edge]] of Object.entries(REACH)) {
    const q = quads('oak_fence', {
      north: side === 'north' ? 'true' : 'false', south: side === 'south' ? 'true' : 'false',
      east: side === 'east' ? 'true' : 'false', west: side === 'west' ? 'true' : 'false',
    });
    const [lo, hi] = bbox(q);
    eq(edge === 0 ? lo[axis] : hi[axis], edge,
      `fence connected only ${side} must reach ${'xyz'[axis]}=${edge}`);
    // and must NOT reach the opposite edge
    const opp = edge === 0 ? hi[axis] : lo[axis];
    ok(edge === 0 ? opp < 16 : opp > 0, `fence connected only ${side} must not reach the opposite edge`);
  }
}
console.log(`   ${pass} ok`);

// ══════════════════════════════════════════════════ 6. walls — the state-space case
// Reference: 3 values per side (none/low/tall) x 2 for `up` x 2 waterlogged = 324 real
// states, 162 visual. This block is here because inferring domains from the multipart
// `when` clauses gave it 32 visual states instead of 162, silently, for every wall type.
console.log('6. wall (the state space that collapsed)');
{
  const e = byName.get('cobblestone_wall');
  eq(e.states.length, 162, 'cobblestone_wall must have 162 VISUAL states (3^4 sides x 2 up)');
  eq(e.properties.north, ['low', 'none', 'tall'], 'wall side domain must include "none"');

  const post = quads('cobblestone_wall', { up: 'true', north: 'none', south: 'none', east: 'none', west: 'none' });
  ok(post.length > 0, 'a wall with only its post must still have geometry');
  const tall = quads('cobblestone_wall', { up: 'true', north: 'tall', south: 'none', east: 'none', west: 'none' });
  const low = quads('cobblestone_wall', { up: 'true', north: 'low', south: 'none', east: 'none', west: 'none' });
  ok(bbox(tall)[1][1] >= bbox(low)[1][1], 'a "tall" wall side must be at least as high as a "low" one');
  ok(bbox(tall)[0][2] === 0 && bbox(low)[0][2] === 0, 'both wall side heights must reach the north edge');
}
console.log(`   ${pass} ok`);

// ══════════════════════════════════════════════════ 7. cross plants — element rotation
// Reference: block/cross has two elements, each rotated 45 degrees about the Y axis with
// rescale:true, shade:false. The corners must NOT be axis-aligned, which is the whole point.
console.log('7. cross plant (45-degree element rotation, rescale, no shading)');
{
  const q = quads('dandelion', {});
  ok(q.length === 4, `a cross plant is 4 quads (2 planes, 2 sides), has ${q.length}`);
  ok(q.every((x) => x.shade === 0), 'cross plants must be unshaded — vanilla sets shade:false');
  ok(q.every((x) => x.cull === -1), 'cross plants must never cull a neighbour face');
  // Reference: block/cross elements run [0.8,0,8]-[15.2,16,8] and [8,0,0.8]-[8,16,15.2].
  // Half-length 7.2, rotated 45 degrees gives +/-5.09, and `rescale` multiplies by
  // 1/cos(45) = 1.4142, restoring +/-7.2 — so the plane spans 0.8..15.2, NOT 0..16.
  // Without rescale it would come out 2.9..13.1 and the plant would visibly shrink.
  const [lo, hi] = bbox(q);
  ok(Math.abs(lo[0] - 0.8) < 0.07 && Math.abs(hi[0] - 15.2) < 0.07,
    `rescaled cross must span x 0.8..15.2, is ${lo[0]}..${hi[0]} (5.09 would mean rescale was skipped)`);
  ok(Math.abs(lo[2] - 0.8) < 0.07 && Math.abs(hi[2] - 15.2) < 0.07,
    `rescaled cross must span z 0.8..15.2, is ${lo[2]}..${hi[2]}`);
  // a rotated plane has corners at differing x AND z, unlike every axis-aligned face
  const q0 = q[0];
  const xs = new Set([q0.p[0], q0.p[3], q0.p[6], q0.p[9]]);
  const zs = new Set([q0.p[2], q0.p[5], q0.p[8], q0.p[11]]);
  ok(xs.size > 1 && zs.size > 1, 'a 45-degree plane must vary in both x and z — it is not axis aligned');
}
console.log(`   ${pass} ok`);

// ══════════════════════════════════════════════════ 8. logs — the axis case
// Reference: oak_log.json. axis=y is the plain model; axis=x is x:90,y:90; axis=z is x:90.
// The end-grain texture must end up on the two faces perpendicular to the axis.
console.log('8. logs (axis rotation puts the end grain on the right two faces)');
{
  const END = 'block/oak_log_top', SIDE = 'block/oak_log';
  const AXIS_FACES = { y: ['up', 'down'], z: ['north', 'south'], x: ['east', 'west'] };
  for (const [axis, ends] of Object.entries(AXIS_FACES)) {
    const q = quads('oak_log', { axis });
    eq(bbox(q), [[0, 0, 0], [16, 16, 16]], `oak_log axis=${axis} is a full cube`);
    ok(q.length === 6, `oak_log axis=${axis} has ${q.length} quads, expected 6`);
    for (const d of DIRS) {
      const want = ends.includes(d) ? END : SIDE;
      const f = face(q, d)[0];
      ok(f, `oak_log axis=${axis} is missing its ${d} face`);
      if (f) eq(tex(f), want, `oak_log axis=${axis} ${d} face texture`);
      if (f) eq(f.cull, DIRS.indexOf(d), `oak_log axis=${axis} ${d} face must cull against ${d}`);
    }
  }
}
console.log(`   ${pass} ok`);

// ══════════════════════════════════════════════════ 9. tint
// Reference: block/grass_block has tintindex 0 on its top face and on the overlay; the side
// dirt and the bottom are untinted. Leaves are tinted on every face. This is what W5's
// biome colour attaches to, and a lost tintindex turns every biome the same green.
console.log('9. tint index (where biome colour attaches)');
{
  const g = quads('grass_block', { snowy: 'false' });
  const up = face(g, 'up')[0];
  eq(up.tint, 0, 'grass block top face must carry tintindex 0');
  eq(face(g, 'down')[0].tint, -1, 'grass block bottom must not be tinted');
  // ⚠ oak_leaves has ZERO visual properties. `distance` and `persistent` are real states
  // (14 of them) but neither changes the model, so the visual state space is exactly one —
  // the visual/real split from D-29, showing up in the place it is easiest to trip over.
  ok(byName.get('oak_leaves').states.length === 1,
    `oak_leaves should have 1 visual state, has ${byName.get('oak_leaves').states.length}`);
  const leaves = quads('oak_leaves', {});
  ok(leaves.every((q) => q.tint === 0), 'every oak_leaves face must carry tintindex 0');
  const snowy = quads('grass_block', { snowy: 'true' });
  ok(face(snowy, 'north')[0] && tex(face(snowy, 'north')[0]).includes('snow'),
    'a snowy grass block must use the snow side texture');
}
console.log(`   ${pass} ok`);

// ══════════════════════════════════════════════════ 10. whole-roster invariants
console.log('10. whole-roster invariants');
{
  let bad = 0, degenerate = 0, offCell = 0, badUv = 0, badTile = 0;
  for (const part of G.parts) {
    for (const q of part) {
      if (q.d < 0 || q.d > 5) bad++;
      if (q.cull < -1 || q.cull > 5) bad++;
      if (tileOf.get(q.t) === undefined) badTile++;
      if (q.p.length !== 12 || q.uv.length !== 8) bad++;
      // a quad with zero area is a quad that costs a draw and shows nothing
      const [ax, ay, az] = [q.p[3] - q.p[0], q.p[4] - q.p[1], q.p[5] - q.p[2]];
      const [bx, by, bz] = [q.p[9] - q.p[0], q.p[10] - q.p[1], q.p[11] - q.p[2]];
      const cr = [ay * bz - az * by, az * bx - ax * bz, ax * by - ay * bx];
      if (Math.hypot(...cr) < 1e-6) degenerate++;
      for (let i = 0; i < 12; i++) if (q.p[i] < -16 || q.p[i] > 32) offCell++;
      for (let i = 0; i < 8; i++) if (q.uv[i] < -0.01 || q.uv[i] > 16.01) badUv++;
    }
  }
  ok(bad === 0, `${bad} quads with a malformed field`);
  ok(badTile === 0, `${badTile} quads referencing a tile that is not in the atlas`);
  ok(degenerate === 0, `${degenerate} zero-area quads — each one costs a draw and shows nothing`);
  ok(offCell === 0, `${offCell} vertex coordinates outside -16..32 — nothing legitimately reaches that far`);
  ok(badUv === 0, `${badUv} uv coordinates outside 0..16`);

  // every visual state of every block must resolve, and only the 21 disconnected walls
  // may resolve to nothing at all.
  let empty = [];
  for (const [name, states] of Object.entries(G.states)) {
    states.forEach((groups, i) => { if (!groups.length) empty.push(`${name}[${i}]`); });
    ok(states.length === byName.get(name).states.length,
      `${name}: ${states.length} geometry states for ${byName.get(name).states.length} registry states`);
  }
  ok(empty.length === 21, `${empty.length} states with no geometry, expected exactly the 21 disconnected walls`);
  ok(empty.every((e) => e.includes('_wall')), `a state with no geometry that is not a wall: ${empty.find((e) => !e.includes('_wall'))}`);
}
console.log(`   ${pass} ok`);

// ══════════════════════════════════════════════════ 11. ANTI-VACUITY (D-30)
// ══════════════════════════════════════════════════ 11. THE ROUND TRIP — PLAN F8's own words
// "the emitted quads are compared against a reference and must match EXACTLY, including
//  cullface identity after rotation and UV orientation under uvlock."
//
// Sections 1-10 above check PROPERTIES — a bounding box, a cullface, one UV rectangle. They
// are worth having and they are not this. This section compares every quad of every case in
// `tools/mesh-reference.mjs` — direction, cullface, texture, tint, shade, all twelve position
// numbers and all eight UV numbers — against a reference that was TYPED OUT BY HAND from the
// model JSON in the jar. Read that file's header before touching it.
//
// Quads are matched as a multiset: the reference does not claim to know what order the baked
// parts come out in, only what they are. Order is a separate question and PLAN does not ask
// this test to answer it.
console.log('11. the round trip against the hand-written reference (PLAN F8)');
{
  const key = (q, tol) => {
    const num = (v) => (tol ? v.toFixed(6) : String(v));
    return [q.d, q.cull, q.t, q.tint, q.shade,
            q.p.map(num).join(','), q.uv.map(num).join(',')].join('|');
  };
  let cases = 0, quadsChecked = 0;
  for (const c of REFERENCE) {
    cases++;
    let got;
    try { got = quads(c.block, c.state, c.alt || 0); }
    catch (e) { fails.push(`${c.block}${JSON.stringify(c.state)}: ${e.message}`); continue; }

    // the reference names textures; the baked quads carry atlas tile numbers
    const norm = got.map((g) => ({ d: g.d, cull: g.cull, t: tex(g), tint: g.tint, shade: g.shade,
                                   p: g.p, uv: g.uv }));
    const want = c.quads.map((w) => ({ ...w, t: w.t }));

    if (norm.length !== want.length) {
      fails.push(`${c.block}${JSON.stringify(c.state)} — ${c.why}\n` +
                 `        expected ${want.length} quads, got ${norm.length}`);
      continue;
    }
    // ── the reference's own self-check ────────────────────────────────────────────────────
    // Every rotated case ALSO states, by hand, which way each of its quads ends up facing.
    // `place()` derives the same thing from the rotation formula, so if that formula were
    // wrong the two would contradict each other HERE — before the baked data is consulted at
    // all. Without this, a reference and a pipeline that share a misconception agree happily.
    if (c.expect) {
      const got = c.quads.map((w) => DIRS[w.d]);
      eq(got, c.expect, `${c.block}${JSON.stringify(c.state)}: the reference's own rotation ` +
        'formula disagrees with the directions written out by hand for this case');
    }

    const pool = new Map();
    for (const g of norm) { const k = key(g, c.tol); pool.set(k, (pool.get(k) || 0) + 1); }
    let bad = 0;
    for (const w of want) {
      const k = key(w, c.tol);
      if (pool.get(k)) { pool.set(k, pool.get(k) - 1); pass++; quadsChecked++; continue; }
      bad++;
      if (bad <= 2) {
        // find the closest actual quad on the same face, so the message says what MOVED
        const near = norm.filter((g) => g.d === w.d && g.cull === w.cull);
        fails.push(`${c.block}${JSON.stringify(c.state)} — ${c.why}\n` +
          `        expected ${JSON.stringify(w)}\n` +
          `        nearest  ${near.length ? JSON.stringify(near[0]) : '(no quad on that face with that cullface)'}`);
      }
    }
    if (bad > 2) fails.push(`${c.block}${JSON.stringify(c.state)}: and ${bad - 2} more quads did not match`);
  }
  ok(cases >= 20, `PLAN F8 asks for at least 20 hand-written cases, this reference has ${cases}`);
  ok(REFERENCE.filter((c) => c.expect).length >= 5,
     'at least five cases must state their post-rotation directions by hand, or the rotation ' +
     'formula in mesh-reference.mjs is checked only against itself');
  console.log(`   ${pass} ok   (${cases} hand-written cases, ${quadsChecked} quads matched exactly)`);
}

console.log('12. anti-vacuity: break it, and it must be caught');
// Each case takes REAL baked data, introduces the specific defect this suite is meant to
// catch, and asserts the corresponding invariant now fails. That is the only construction
// that proves the invariant is load-bearing rather than decorative (D-30).
const av = [];
const brk = (label, invariant, breaker) => {
  const good = invariant(breaker(false));
  const bad = invariant(breaker(true));
  av.push([label, good === true && bad === false]);
};

brk('a stair whose tall step did not move when rotated',
  (pair) => JSON.stringify(pair[0]) !== JSON.stringify(pair[1]),
  (broken) => {
    const e = quads('oak_stairs', { facing: 'east', half: 'bottom', shape: 'straight' });
    const w = quads('oak_stairs', { facing: 'west', half: 'bottom', shape: 'straight' });
    return broken ? [e, e] : [e, w];
  });

brk('a slab whose side UV starts at 0 instead of 8',
  (q) => q.uv[1] === 8,
  (broken) => {
    const f = { ...face(quads('oak_slab', { type: 'bottom' }), 'north')[0] };
    f.uv = f.uv.slice();
    if (broken) { f.uv[1] = 0; f.uv[3] = 0; }
    return f;
  });

brk('a fence that lost its arms',
  (pair) => pair[1].length > pair[0].length,
  (broken) => {
    const none = quads('oak_fence', { north: 'false', south: 'false', east: 'false', west: 'false' });
    const all = quads('oak_fence', { north: 'true', south: 'true', east: 'true', west: 'true' });
    return broken ? [none, none] : [none, all];
  });

brk('a wall whose state space collapsed to the triggering values only',
  (n) => n === 162,
  (broken) => (broken ? 2 * 2 ** 4 : byName.get('cobblestone_wall').states.length));

brk('a log whose end grain is on every face',
  (qs) => new Set(qs.map(tex)).size === 2,
  (broken) => {
    const q = quads('oak_log', { axis: 'y' });
    return broken ? q.map((x) => ({ ...x, t: q[0].t })) : q;
  });

brk('a grass block that lost its tint index',
  (qs) => qs.some((x) => x.tint === 0),
  (broken) => {
    const q = quads('grass_block', { snowy: 'false' });
    return broken ? q.map((x) => ({ ...x, tint: -1 })) : q;
  });

brk('random model alternatives drawn all at once instead of one-of',
  (n) => n === 6,
  (broken) => (broken ? alternatives('stone', {}).flat().length : quads('stone', {}).length));

// ── the round trip's own anti-vacuity ─────────────────────────────────────────────────────
// Section 11 is the one that matters most and it is also the easiest to write vacuously: a
// comparison that always finds a match proves nothing at all. These three take the SAME
// matching function section 11 uses and feed it a reference with one number changed, and
// require it to notice. One per kind of number, because they fail differently: a position
// moves geometry, a UV moves the picture on it, and a cullface makes a hole in the world.
const refKey = (q) => [q.d, q.cull, q.t, q.tint, q.shade, q.p.join(','), q.uv.join(',')].join('|');
const matchAll = (want, got) => {
  const pool = new Map();
  for (const g of got) { const k = refKey(g); pool.set(k, (pool.get(k) || 0) + 1); }
  for (const w of want) { const k = refKey(w); if (!pool.get(k)) return false; pool.set(k, pool.get(k) - 1); }
  return true;
};
const slabRef = REFERENCE.find((c) => c.block === 'oak_slab' && c.state.type === 'bottom');
const slabGot = () => quads('oak_slab', { type: 'bottom' })
  .map((g) => ({ d: g.d, cull: g.cull, t: tex(g), tint: g.tint, shade: g.shade, p: g.p, uv: g.uv }));

brk('the round trip matching a reference whose geometry moved one unit',
  (v) => v === true,
  (broken) => {
    const want = slabRef.quads.map((w) => (broken ? { ...w, p: w.p.map((n, i) => (i === 1 ? n + 1 : n)) } : w));
    return matchAll(want, slabGot());
  });

brk('the round trip matching a reference whose UV was normalised',
  (v) => v === true,
  (broken) => {
    // the trapdoor's [0,16,16,13] read as [0,13,16,16] — the min/max flattening that section
    // 19 of the reference exists to catch
    const ref = REFERENCE.find((c) => c.block === 'oak_trapdoor' && c.state.half === 'bottom');
    const got = quads('oak_trapdoor', { facing: 'north', half: 'bottom', open: 'false' })
      .map((g) => ({ d: g.d, cull: g.cull, t: tex(g), tint: g.tint, shade: g.shade, p: g.p, uv: g.uv }));
    const want = ref.quads.map((w) => (broken
      ? { ...w, uv: w.uv.map((n, i) => (i % 2 === 1 ? (n === 16 ? 13 : n === 13 ? 16 : n) : n)) }
      : w));
    return matchAll(want, got);
  });

brk('the round trip matching a reference whose cullface was dropped',
  (v) => v === true,
  (broken) => {
    const want = slabRef.quads.map((w) => (broken ? { ...w, cull: -1 } : w));
    return matchAll(want, slabGot());
  });

for (const [label, caught] of av) {
  ok(caught, `ANTI-VACUITY FAILURE: "${label}" — the invariant does not distinguish good data from broken data, so it proves nothing`);
  console.log(`   ${caught ? '✓' : '✗'} ${label}`);
}

console.log('');
console.log('================ meshcheck ================');
console.log(` assertions passed .. ${pass}`);
console.log(` failures ........... ${fails.length}`);
for (const f of fails.slice(0, 30)) console.log('   ✗ ' + f);
if (fails.length > 30) console.log(`   ... and ${fails.length - 30} more`);
console.log('');
console.log(` parts ${G.parts.length} · quads ${G.parts.reduce((a, p) => a + p.length, 0)} · blocks ${Object.keys(G.states).length}`);
console.log('==========================================');
process.exit(fails.length ? 1 : 0);
